  if (on('jewish')){ if (inH([['Elul', 22, 30], ['Tishri', 1, 3]])) return 'roshhashana'; if (inH([['Kislev', 24, 30], ['Tevet', 1, 3]])) return 'hanukkah'; if (inH([['Nisan', 10, 22]])) return 'passover'; }
