  $$('#panels input[id],#panels select[id]').forEach(e => { if (e.type === 'range' || /^(set_|x_from|x_to)/.test(e.id) || e.classList.contains('scn-name')) return; o[e.id] = e.value; });
  o.__touched = TOUCHED.join(',');
