  if (el.closest('#rc_back')){ ['in', 'up', 'mv', 'rc'].forEach(k => { const f = $('#acc_f_' + k); if (f) f.hidden = k !== 'in'; }); const u = $('#acc_user'), r = $('#rc_user'); if (u && r && r.value) u.value = r.value; return; }
