  const autoTxt = x => { const d = LN_DEL[LN.cfg.del]; if (!/^auto/.test(LN.cfg.del) || x.st !== 'stale') return ''; const left = (x.sa || Date.now()) + d - Date.now(); return left <= 0 ? t('ln_autoNow') : t('ln_autoIn', {t: srcWhen((x.sa || Date.now()) + d)}); };
