  try { await srcpSave(next); try { s.blur(); } catch (err) {} srcpSet(next); toast(t('src_pSaved', {g: t('src_g_' + g), s: t('src_p_' + g + '_' + SRCP[g])})); }
  catch (err) { srcpSet(prev); srcRender(true); toast(t('src_pFail')); }
