function aiChipKeys(id){ return id === 'home' ? ['ai_cHome', 'ai_cWhich'] : id === 'expenses' ? ['ai_cExp', 'ai_cWhich'] : ['settings', 'clients', 'assist'].includes(id) ? ['ai_cWhich'] : ['ai_cExplain', 'ai_cImpact', 'ai_cFill', 'ai_cImprove']; }
