function aiRich(s){ return pmLinkify(exFmt(s)).replace(/\[\[([a-z0-9]+)(?:\|([^\]]*))?\]\]/g, (_, c, f) => TABS.includes(c) && c !== 'assist' ? `<button type="button" class="as-go" data-aigo="${c}"${f ? ` data-aifill="${f}"` : ''}>${asEsc(f ? t('pm_openWith', {n: t('tab_' + c)}) : t('tab_' + c))}</button>` : ''); }
