  const g = e.target.closest('[data-aigo]'); if (g){ activate(g.dataset.aigo); aiOpenFor(g.dataset.aigo, true); aiLog('ai', t('ai_moved', {n: t('tab_' + g.dataset.aigo)})); return; }
