const MK_COIN = [[/דולר|دولار|dollar/i, 'USD'], [/אירו|يورو|euro/i, 'EUR'], [/ביטקוין|بيتكوين|bitcoin/i, 'BTC'], [/אית׳ריום|إيثريوم|ethereum/i, 'ETH'], [/ליש״ט|לירה שטרלינג|جنيه إسترليني|pound/i, 'GBP']];
