    try { RAWLS.setItem('fin-fam-u', u); RAWLS.setItem('fin-fam-pw', pw); RAWLS.setItem('fin-fam-pwat', String(at)); if (relay) RAWLS.setItem('fin-fam-pend', String(at)); } catch (er) {}
