  if (k === 'ils'){ const own = +((SET.phPrice || {})[p.id]); return own > 0 ? own : ''; }
  if (k === 'pr0') return p.pr ? p.pr[0] : '';
  if (k === 'cam') return (p.cam || []).join('+');
