      <select id="mx_dec" aria-label="${mE(t('mx_dec'))}" title="${mE(t('mx_dec'))}"><option value="">${mE(t('mx_decAuto'))}</option>${[0, 2, 4, 6, 10].map(n => `<option value="${n}"${String(d.dec) === String(n) ? ' selected' : ''}>${n}</option>`).join('')}</select>
