function pxObjName(o){ const n = t('px_o_' + (o.t === 'mark' ? o.k : o.t === 'pen' && o.hl ? 'hl' : o.base ? 'scan' : o.sig ? 'sign' : o.qr ? 'qr' : o.stamp ? 'stamp' : o.t)); return o.t === 'text' ? n + ': ' + (String(o.txt || '').slice(0, 30) || '…') : n; }
