    try { if (PX.task && PX.task.cancel) PX.task.cancel(); } catch (e) {}
    try { const c = await pxPageCanvas(p, k * dpr); if (my !== PX_DRAW) return; pc.width = c.width; pc.height = c.height; pc.getContext('2d').drawImage(c, 0, 0); PX.cache = {key}; }
