  const W = pxW(p), H = pxH(p), M = 26, out = [], txt = (s, top, al, fs) => out.push({t: 'text', x: M, y: top ? M * 0.7 : H - M * 0.7 - fs * 1.5, w: W - 2 * M, txt: s, fs, col: D.col || '#333333', font: 'sans', b: false, it: false, al, bg: '', op: 1, deco: true});
