const tfLangN = (code, l) => { try { const n = new Intl.DisplayNames([l || lang], {type: 'language'}).of(code); return n ? n.charAt(0).toLocaleUpperCase(l || lang) + n.slice(1) : code; } catch (e) { return code; } };
