  let net = rows.reduce((s, r) => s + r.net, 0);
  if (grp === 'il' && net > 0){ if (d.meth === 'cash') net -= net * 0.01 * 1.18; else if (d.meth === 'transfer') net -= 47.5; net = Math.max(0, net); }
