    if (it.done) it.done = false; else if (it.rep !== 'none'){ let n = rmNext(it.date, it.rep), g = 0; while (rmDays(n) < 0 && g++ < 600) n = rmNext(n, it.rep); it.date = n; toast(t('rm_movedTo', {d: rmFmt(n)})); } else it.done = true;
