  v.innerHTML = `<p class="fine">${E(t('lp_mIntro'))}</p>${side('A')}${side('B')}<div class="bk-grid">${lpIn('m_kmc', t('lp_mKmc'), '1.5', '₪')}${lpIn('m_days', t('lp_mDays'), '21')}${lpIn('m_once', t('lp_mOnce'), '12000', '₪')}</div><div id="lp_out" aria-live="polite"></div>`;
  lpMoveOut();
