  const cost = s => lpV('m' + s + '_rent', s === 'A' ? 5500 : 4500) + lpV('m' + s + '_arn', 450) + lpV('m' + s + '_km', s === 'A' ? 10 : 35) * 2 * days * kmc + lpV('m' + s + '_pt', 0) + lpV('m' + s + '_kid', 0) + lpV('m' + s + '_oth', 0);
