    const UL = {he: 'Hebrew', ar: 'Arabic', en: 'English'}[lang] || 'English'; btn.disabled = true;
    o.hidden = false; o.innerHTML = `<p class="fine">⏳ ${csE(t('mx_aiWait'))}</p>`;
