      tips: [t('ml_t_pay'), t('ml_t_tax'), t('ml_t_family'), t('ml_t_birth'), t('ml_t_more'), t('ml_t_job'), t('ml_t_arnona'), t('ml_t_student')],
      note: t('ml_note'),
