/* ---------- 13.8: moving to a new address without losing anything ----------
   The browser keeps the app's data per address, so a new domain starts empty. When MIG_TO is set:
   • on the old address the app shows "the app has moved": one tap opens the new address and hands it all the data
     directly, phone to phone (window.postMessage between the two tabs – no server, nothing in the link);
   • on the new address the app receives it, but only from the old addresses listed here.
   Encrypted accounts stay encrypted. Leave MIG_TO empty until the new address is live. */
const MIG_TO = 'https://financial-calculator.design-il.workers.dev';                                         // e.g. 'https://example.co.il' – no trailing slash
const MIG_FROM = ['https://ysdesign-il.github.io'];
const migE = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const migKeys = () => { const L = []; try { for (let i = 0; i < RAWLS.length; i++){ const k = RAWLS.key(i); if (k && k.indexOf('fin-') === 0 && k !== 'fin-migrated') L.push(k); } } catch (e) {} return L; };
const migItems = () => { const o = {}; migKeys().forEach(k => { try { o[k] = RAWLS.getItem(k); } catch (e) {} }); return o; };
const migGo = () => location.replace(MIG_TO + '/' + location.search + (location.hash && !/^#mig/.test(location.hash) ? location.hash : ''));
function migOverlay(html){
  let o = $('#migx'); if (!o){ document.body.insertAdjacentHTML('beforeend', `<div class="mig-ov" id="migx" role="dialog" aria-modal="true" aria-labelledby="migx_t"><div class="mig-box" id="migx_b"></div></div>`); o = $('#migx'); }
  $('#migx_b').innerHTML = html; document.body.classList.add('cp-lock'); setTimeout(() => { const b = $('#migx_b button'); if (b) b.focus(); }, 30);
}
const migHost = () => { let h = MIG_TO; try { h = new URL(MIG_TO).host; } catch (e) {} return '\u2068' + h + '\u2069'; };

/* ---------- the old address ---------- */
var MIGS = {w: null, t: null, sent: false};
function migOld(){
  const n = (typeof FIN_K0 !== 'undefined' ? FIN_K0 : migKeys()).filter(k => !['fin-migrated', 'fin-ver', 'fin-tab', 'fin-lang', 'fin-upd-ntf', 'fin-fam-list'].includes(k)).length;
  let done = ''; try { done = RAWLS.getItem('fin-migrated') || ''; } catch (e) {}
  if (done || !n){ migGo(); return; }
  migOverlay(`<div class="mig-ic" aria-hidden="true">🚚</div><h2 id="migx_t">${migE(t('mig_t'))}</h2>
    <p>${migE(t('mig_h', {d: migHost()}))}</p>
    <div class="btnrow mig-btns"><button type="button" class="gold-btn" id="mig_go">📦 ${migE(t('mig_go'))}</button></div>
    <p class="fine">🔒 ${migE(t('mig_priv'))}</p>
    <div class="sl-st" id="mig_st" aria-live="polite"></div>
    <button type="button" class="lg-a" id="mig_skip">${migE(t('mig_skip'))}</button>`);
}
function migSend(){
  const items = migItems(); MIGS.sent = false;
  MIGS.w = window.open(MIG_TO + '/#mig', '_blank');
  const st = $('#mig_st');
  if (!MIGS.w){ migLink(items); return; }
  if (st){ st.textContent = t('mig_wait'); st.className = 'sl-st'; }
  clearTimeout(MIGS.t); MIGS.t = setTimeout(() => { if (!MIGS.sent){ const s = $('#mig_st'); if (s){ s.textContent = t('mig_slow'); s.className = 'sl-st bad'; } } }, 12000);
}
/* if the browser blocked the new tab: the data travels in the part of the link after #, which browsers never send to any server */
async function migLink(items){
  try {
    const raw = new TextEncoder().encode(JSON.stringify(items));
    let bytes = raw, z = '0';
    if (typeof CompressionStream === 'function'){ bytes = new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer()); z = '1'; }
    let bin = ''; for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    const b64 = btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    if (b64.length > 1500000){ const s = $('#mig_st'); if (s){ s.textContent = t('mig_big'); s.className = 'sl-st bad'; } return; }
    try { RAWLS.setItem('fin-migrated', String(Date.now())); } catch (e) {}
    location.href = MIG_TO + '/#migz=' + z + b64;
  } catch (e) { const s = $('#mig_st'); if (s){ s.textContent = t('mig_big'); s.className = 'sl-st bad'; } }
}
window.addEventListener('message', e => {
  if (!MIG_TO || e.origin !== MIG_TO || !e.data || typeof e.data !== 'object') return;
  if (e.data.type === 'mig-ready' && MIGS.w && !MIGS.sent){ MIGS.sent = true; try { MIGS.w.postMessage({type: 'mig-data', v: 1, items: migItems()}, MIG_TO); } catch (er) {} return; }
  if (e.data.type === 'mig-done'){ clearTimeout(MIGS.t); try { RAWLS.setItem('fin-migrated', String(Date.now())); } catch (er) {}
    migOverlay(`<div class="mig-ic" aria-hidden="true">✅</div><h2 id="migx_t">${migE(t('mig_done'))}</h2><p>${migE(t('mig_doneH', {d: migHost()}))}</p>
      <div class="btnrow mig-btns"><button type="button" class="gold-btn" id="mig_open">↗ ${migE(t('mig_open'))}</button></div>`); }
});

/* ---------- the new address ---------- */
function migApply(items){
  if (!items || typeof items !== 'object') return false;
  const keys = Object.keys(items).filter(k => /^fin-[\w:.\-+=/]*$/.test(k) && k !== 'fin-migrated' && typeof items[k] === 'string');
  if (!keys.length) return false;
  let mine = 0; try { mine = migKeys().filter(k => !['fin-lang', 'fin-ver', 'fin-tab', 'fin-upd-ntf'].includes(k)).length; } catch (e) {}
  if (mine > 2 && !confirm(t('mig_over'))) return false;
  keys.forEach(k => { try { RAWLS.setItem(k, items[k]); } catch (e) {} });
  return true;
}
function migNew(){
  const h = location.hash || '';
  if (h === '#mig' && window.opener){
    try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}
    migOverlay(`<div class="mig-ic" aria-hidden="true">📥</div><h2 id="migx_t">${migE(t('mig_recv'))}</h2><p class="fine">${migE(t('mig_recvH'))}</p>`);
    const ok = e => {
      if (!MIG_FROM.includes(e.origin) || !e.data || e.data.type !== 'mig-data') return;
      window.removeEventListener('message', ok);
      const applied = migApply(e.data.items);
      try { e.source.postMessage({type: applied ? 'mig-done' : 'mig-no'}, e.origin); } catch (er) {}
      if (applied){ migOverlay(`<div class="mig-ic" aria-hidden="true">✅</div><h2 id="migx_t">${migE(t('mig_ok'))}</h2>`); setTimeout(() => location.reload(), 900); }
      else { const o = $('#migx'); if (o) o.remove(); document.body.classList.remove('cp-lock'); }
    };
    window.addEventListener('message', ok);
    MIG_FROM.forEach(o => { try { window.opener.postMessage({type: 'mig-ready'}, o); } catch (e) {} });
    return;
  }
  if (h.indexOf('#migz=') === 0){
    const data = h.slice(6);
    try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}       // the data leaves the address bar at once
    (async () => {
      try {
        const z = data.charAt(0), b64 = data.slice(1).replace(/-/g, '+').replace(/_/g, '/'), bin = atob(b64 + '==='.slice((b64.length + 3) % 4)), u = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
        const txt = z === '1' ? await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).text() : new TextDecoder().decode(u);
        if (migApply(JSON.parse(txt))){ toast(t('mig_ok')); setTimeout(() => location.reload(), 900); }
      } catch (e) { toast(t('mig_fail')); }
    })();
  }
}
document.addEventListener('click', e => {
  if (!e.target.closest) return;
  if (e.target.closest('#mig_go')){ migSend(); return; }
  if (e.target.closest('#mig_skip')){ try { RAWLS.setItem('fin-migrated', 'skip'); } catch (er) {} migGo(); return; }
  if (e.target.closest('#mig_open')){ if (MIGS.w && !MIGS.w.closed){ try { MIGS.w.focus(); return; } catch (er) {} } migGo(); return; }
});
try {
  if (MIG_TO && typeof IN_CLAUDE !== 'undefined' && !IN_CLAUDE){
    if (MIG_FROM.includes(location.origin)) migOld(); else if (location.origin === MIG_TO) migNew();
  }
} catch (e) {}

/* 13.43: the floating buttons (accessibility, AI assistant, admin) can be dragged anywhere; the place is kept on this phone.
   A tap still works as a tap. A long press (without moving) puts the button back in its usual place. */
function fabDrag(sels, KEY){
  const load = () => { try { return JSON.parse(LS.getItem(KEY) || '{}') || {}; } catch (e) { return {}; } };
  const save = o => { try { LS.setItem(KEY, JSON.stringify(o)); } catch (e) {} };
  const P = ['left', 'top', 'right', 'bottom', 'inset-inline-start', 'inset-inline-end', 'transform'];
  const put = (el, x, y) => { const r = el.getBoundingClientRect(), W = innerWidth, H = innerHeight, m = 6;
    const L = Math.max(m, Math.min(W - r.width - m, x * W - r.width / 2)), T = Math.max(m, Math.min(H - r.height - m, y * H - r.height / 2));
    P.forEach(k => el.style.setProperty(k, 'auto', 'important')); el.style.setProperty('transform', 'none', 'important');
    el.style.setProperty('left', L + 'px', 'important'); el.style.setProperty('top', T + 'px', 'important'); };
  const keyOf = el => sels.find(s => el.matches(s));
  const apply = el => { const k = keyOf(el), o = load()[k]; if (o && isFinite(o.x) && isFinite(o.y)) put(el, o.x, o.y); };
  const reset = el => { P.forEach(k => el.style.removeProperty(k)); const o = load(); delete o[keyOf(el)]; save(o); };
  function attach(el){
    if (el.__fd) { apply(el); return; } el.__fd = 1; el.style.touchAction = 'none'; apply(el);
    let s = null, moved = false, eat = false, lp = 0;
    el.addEventListener('pointerdown', e => { if (e.button > 0) return; const r = el.getBoundingClientRect(); s = {x: e.clientX, y: e.clientY, dx: e.clientX - r.left, dy: e.clientY - r.top, id: e.pointerId}; moved = false; try { el.setPointerCapture(e.pointerId); } catch (er) {}
      clearTimeout(lp); lp = setTimeout(() => { if (s && !moved){ s = null; eat = true; reset(el); try { navigator.vibrate && navigator.vibrate(20); } catch (er) {} } }, 900); });
    el.addEventListener('pointermove', e => { if (!s || e.pointerId !== s.id) return;
      if (!moved && Math.hypot(e.clientX - s.x, e.clientY - s.y) < 8) return;
      if (!moved){ moved = true; clearTimeout(lp); el.classList.add('fd-drag'); }
      const r = el.getBoundingClientRect(); put(el, (e.clientX - s.dx + r.width / 2) / innerWidth, (e.clientY - s.dy + r.height / 2) / innerHeight); e.preventDefault(); });
    const end = e => { clearTimeout(lp); if (!s) return; if (moved){ const r = el.getBoundingClientRect(), o = load(); o[keyOf(el)] = {x: (r.left + r.width / 2) / innerWidth, y: (r.top + r.height / 2) / innerHeight}; save(o); eat = true; el.classList.remove('fd-drag'); } s = null; };
    el.addEventListener('pointerup', end); el.addEventListener('pointercancel', end);
    el.addEventListener('click', e => { if (eat){ eat = false; e.preventDefault(); e.stopImmediatePropagation(); } }, true);
    el.addEventListener('contextmenu', e => { if (s || eat) e.preventDefault(); });
  }
  const scan = () => sels.forEach(q => document.querySelectorAll(q).forEach(attach));
  let t = 0; new MutationObserver(() => { clearTimeout(t); t = setTimeout(scan, 60); }).observe(document.body, {childList: true, subtree: true});
  addEventListener('resize', () => { clearTimeout(t); t = setTimeout(scan, 120); });
  scan();
  return {reset: () => { save({}); sels.forEach(q => document.querySelectorAll(q).forEach(el => P.forEach(k => el.style.removeProperty(k)))); }};
}
const FABDRAG = fabDrag(['.ax-fab', '.ai-fab', '#admk-fab'], 'fin-fabpos');
/* in the accessibility panel: put all floating buttons back in place */
if (typeof axPanel === 'function'){ const axpFd = axPanel; axPanel = function(){ const r = axpFd.apply(this, arguments); try { const f = document.querySelector('#axx_b .ax-foot'); if (f && !f.querySelector('#fd_reset')) f.insertAdjacentHTML('beforeend', `<button type="button" class="btn" id="fd_reset">⤢ ${axE(t('fd_reset'))}</button>`); } catch (e) {} return r; }; }
document.addEventListener('click', e => { if (e.target.closest && e.target.closest('#fd_reset')){ FABDRAG.reset(); toast(t('fd_done')); } });
Object.assign(T, {
  fd_reset:['החזרת הכפתורים הצפים למקום','إعادة الأزرار العائمة إلى مكانها','Put floating buttons back'],
  fd_done:['הכפתורים חזרו למקום. אפשר לגרור אותם שוב לכל מקום.','عادت الأزرار إلى مكانها. يمكن سحبها مجددًا إلى أي مكان.','Buttons are back in place. You can drag them anywhere again.'],
});

/* 13.47: what the owner sets in the admin panel reaches the app as window.__ADMCFG (event 'admp-cfg'):
   1) calculators switched off one by one (cfg.offTabs, cfg.offMsg): hidden from every menu, and a link to one goes to the home
      screen with the owner's note. The admin version keeps everything open.
   2) the owner's published values (cfg.fig = {v, asOf}): the same official values as figures.json; the newest wins.
   In the admin version the app lists its screens for the panel (window.__ADM_SCREENS__), and the values editor can publish to everyone. */
const admIn = () => window.__FIN_ADMSES__ === 1;
var KS_OFF = [], KS_MSG = '', ADM_FIG = null;
function ksApply(c){
  KS_OFF = admIn() ? [] : (Array.isArray(c.offTabs) ? c.offTabs : []).filter(id => typeof id === 'string' && TABS.includes(id) && id !== 'home' && id !== 'settings');
  KS_MSG = String(c.offMsg || '').slice(0, 200);
  let st = document.getElementById('ks-st'); if (!st){ st = document.createElement('style'); st.id = 'ks-st'; document.head.appendChild(st); }
  st.textContent = KS_OFF.length ? KS_OFF.map(id => `button[data-go="${id}"],button[data-tab="${id}"],a[data-go="${id}"]`).join(',') + '{display:none!important}' : '';
  if (KS_OFF.includes(tab)) activate('home');
}
const activateKs = activate;
activate = function(id){
  if (KS_OFF.includes(id)){ try { toast(KS_MSG || t('ks_off')); } catch (e) {} return activateKs.call(this, 'home'); }
  return activateKs.apply(this, arguments);
};
/* the owner's values: newer than figures.json → used instead of it */
const figOfficialSetAdm = figOfficialSet;
figOfficialSet = function(d, src){
  if (ADM_FIG && +ADM_FIG.asOf > (+(d && d.asOf) || 0)) return figOfficialSetAdm.call(this, ADM_FIG, 'site');
  return figOfficialSetAdm.apply(this, arguments);
};
function figAdmApply(c){
  const f = c && c.fig;
  if (!f || typeof f !== 'object' || !f.v || typeof f.v !== 'object' || !(+f.asOf > 0)){ if (ADM_FIG){ ADM_FIG = null; figOfficialSetAdm({v: {}, asOf: 0}, 'built'); try { figSite(); } catch (e) {} } return; }
  if (ADM_FIG && +ADM_FIG.asOf === +f.asOf) return;
  ADM_FIG = {v: f.v, asOf: +f.asOf}; figOfficialSetAdm(ADM_FIG, 'site');
}
function admCfg(){ const c = window.__ADMCFG; if (!c || typeof c !== 'object') return; try { ksApply(c); } catch (e) {} try { figAdmApply(c); } catch (e) {} }
addEventListener('admp-cfg', admCfg); admCfg();

/* ---- admin version only ---- */
function admScreens(){ if (admIn()) window.__ADM_SCREENS__ = TABS.filter(id => id !== 'home' && id !== 'settings').map(id => { const x = T['tab_' + id] || []; return [id, x[0] || t('tab_' + id), x[2] || ''] }); }
admScreens();
const fgRenderAdm = fgRender;
fgRender = function(){
  const r = fgRenderAdm.apply(this, arguments);
  try {
    const box = $('#fg_box');
    if (box && !IN_CLAUDE && admIn() && liveOwner() && !box.querySelector('.fg-own')){
      box.insertAdjacentHTML('beforeend', `<div class="fg-own"><b>${asEsc(t('fg_ownT'))}</b><p class="fine">${asEsc(t('fg_pubS'))} ${asEsc(t('fg_admHist'))}</p><div class="btnrow"><button type="button" class="gold-btn" id="fg_pub2">${asEsc(t('fg_pub'))}</button>${ADM_FIG ? `<button type="button" class="mv wide" id="fg_unpub2">${asEsc(t('fg_unpub'))}</button>` : ''}</div><p class="fine" id="fg_pubMsg2"></p></div>`);
    }
  } catch (e) {}
  return r;
};
const fgDesc = (f, v) => { try { return t(f.lab, f.p) + ': ' + fgVal(f, v); } catch (e) { return f.id + ': ' + v; } };
document.addEventListener('click', async e => {
  const pb = e.target.closest && e.target.closest('#fg_pub2, #fg_unpub2'); if (!pb) return;
  if (!pb.dataset.sure){ pb.dataset.sure = '1'; pb.textContent = t('fg_pubSure'); return; }
  const msg = $('#fg_pubMsg2'), un = pb.id === 'fg_unpub2';
  if (typeof window.__ADMKIT_SAVE !== 'function'){ if (msg) msg.textContent = t('fg_pubErr'); return; }
  const v = {}, ch = [];
  if (!un) FG_LIST.forEach(f => { if (FG_MARKET.includes(f.id)) return; const cur = fgR(f.get()); if (Math.abs(cur - FG_BUILT[f.id]) > 1e-9) v[f.id] = cur; if (Math.abs(cur - FG_OFF[f.id]) > 1e-9) ch.push(fgDesc(f, FG_OFF[f.id]) + ' → ' + fgVal(f, cur)); });
  const note = un ? 'ערכים: חזרה לערכים המובנים' : 'ערכים: ' + (ch.length ? ch.slice(0, 4).join(' · ') + (ch.length > 4 ? ' ועוד ' + (ch.length - 4) : '') : 'פורסמו מחדש');
  pb.disabled = true;
  try {
    await window.__ADMKIT_SAVE({fig: un ? null : {v, asOf: Date.now()}}, note);
    const ov = Object.assign({}, fgOv()); Object.keys(ov).forEach(k => { if (!FG_MARKET.includes(k)) delete ov[k]; }); SET.figOv = ov; saveSet();
    if (un && ADM_FIG){ ADM_FIG = null; figOfficialSetAdm({v: {}, asOf: 0}, 'built'); try { figSite(); } catch (er) {} }
    figApply(true); toast(t(un ? 'fg_unpubOk' : 'fg_pubOk'));
  } catch (err) { pb.disabled = false; if (msg) msg.textContent = t('fg_pubErr'); }
});
Object.assign(T, {
  ks_off:['המחשבון הזה סגור זמנית. נחזור בקרוב.','هذه الحاسبة مغلقة مؤقتًا. نعود قريبًا.','This calculator is closed for now. Back soon.'],
  fg_admHist:['כל פרסום נשמר בהיסטוריה בלוח הניהול, ואפשר לשחזר ממנה בלחיצה.','كل نشر يُحفظ في السجل في لوحة الإدارة، ويمكن الاستعادة منه بنقرة.','Every publish is kept in the admin panel history and can be restored in one tap.'],
});

applyLang(false);
activate(tab);
tryLive(false);
